def tr(nl, en, tag='span', attrs=''):
    return f'<{tag} data-nl="{escape(nl, quote=True)}" data-en="{escape(en, quote=True)}"{attrs}>{escape(nl)}</{tag}>'


def paragraph(nl, en, attrs=''):
    return tr(nl, en, 'p', attrs)


def rules(items):
    return '<ul class="rules">'+''.join(tr(nl, en, 'li') for nl, en in items)+'</ul>'


def section(key, number, title, english, body):
    return f'<section id="{key}" aria-labelledby="title-{key}"><div class="section-head"><span class="section-number">{number}</span>'+tr(title, english, 'h2', f' id="title-{key}"')+'</div>'+body+'</section>'


