SCRIPT = r'''
(()=>{'use strict';const key='overtake-it-away-language';let language='nl';try{if(localStorage.getItem(key)==='en')language='en';}catch{}
function translate(){document.documentElement.lang=language;const meta=document.querySelector('meta[name=description]');meta.content=meta.getAttribute('data-description-'+language);document.querySelectorAll('[data-label-nl][data-label-en]').forEach(el=>el.setAttribute('aria-label',el.getAttribute('data-label-'+language)));document.querySelectorAll('[data-nl][data-en]').forEach(el=>{el.textContent=el.dataset[language];});document.querySelectorAll('[data-lang]').forEach(el=>el.classList.toggle('active',el.dataset.lang===language));document.getElementById('guide-language').setAttribute('aria-label',language==='nl'?'Switch to English':'Schakel naar Nederlands');document.title=language==='nl'?'Stijlgids · Overtake It Away':'Style guide · Overtake It Away';}
document.getElementById('guide-language').addEventListener('click',()=>{language=language==='nl'?'en':'nl';try{localStorage.setItem(key,language);}catch{}translate();});document.getElementById('guide-print').addEventListener('click',()=>window.print());
const activeDemo=document.getElementById('guide-toggle-active');activeDemo.addEventListener('click',()=>activeDemo.setAttribute('aria-pressed',String(activeDemo.getAttribute('aria-pressed')!=='true')));
const dialog=document.getElementById('guide-dialog');let opener;
document.getElementById('guide-open-dialog').addEventListener('click',()=>{opener=document.activeElement;dialog.showModal();document.body.classList.add('dialog-open');document.getElementById('guide-close-dialog').focus();});document.getElementById('guide-close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');opener?.focus();});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});translate();
})();
'''


def chart_example():
    """A functioning horizontal-scroll example, never presented as real data."""
    ys = [(10,30),(6,54),(3,78),(1,102),(0,126),(-1,150),(-3,174),(-6,198),(-10,222)]
    axis='<svg class="chart-axis" width="88" height="280" viewBox="0 0 88 280" role="img" aria-label="Y-as" data-label-nl="Y-as" data-label-en="Y axis">'
    axis+=''.join(f'<text x="79" y="{y+4}" text-anchor="end">{format(v,"+d") if v else "0"}</text>' for v,y in ys)
    axis+='<path d="M25 120V39M20 45L25 37L30 45" fill="none" stroke="#36d398" stroke-width="2"/><path d="M25 132V214M20 207L25 215L30 207" fill="none" stroke="#ff4758" stroke-width="2"/>'
    axis+='<text class="better" transform="translate(13 82) rotate(-90)" text-anchor="middle">'+tr('Beter','Better','tspan')+'</text><text class="worse" transform="translate(13 174) rotate(-90)" text-anchor="middle">'+tr('Slechter','Worse','tspan')+'</text></svg>'
    graph='<svg class="chart-body" width="1100" height="280" viewBox="0 0 1100 280" role="img" aria-label="Voorbeeld" data-label-nl="Voorbeeld" data-label-en="Example">'
    graph+=''.join(f'<line x1="0" x2="1090" y1="{y}" y2="{y}" stroke="'+('#51d6dd' if v==0 else '#344053')+'" stroke-dasharray="'+('3 6' if v==0 else 'none')+'"/>' for v,y in ys)
    for i,y in enumerate([126,130,114,109,105,94,82,99,88,73,78,57,72,66,80,52,48,65,60,54]):
        x=30+i*54
        graph+=f'<line x1="{x}" x2="{x}" y1="{y-12}" y2="{y+14}" stroke="#b45cff" stroke-width="7" stroke-linecap="round"/><line x1="{x-9}" x2="{x+9}" y1="{y}" y2="{y}" stroke="white" stroke-width="3"/><text x="{x}" y="252" text-anchor="middle">P{i+1}</text>'
    return '<div class="chart-frame">'+axis+'<div class="chart-scroll" tabindex="0" role="region" aria-label="Horizontaal scrollbare voorbeeldgrafiek" data-label-nl="Horizontaal scrollbare voorbeeldgrafiek" data-label-en="Horizontally scrollable example chart">'+graph+'</svg></div></div>'


def render_style_guide(drivers_available=True):
    logo=b64encode((Path(__file__).parent/'assets/overtake-wordmark-v2.png').read_bytes()).decode()
    head='<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" data-description-nl="Tweetalige stijlgids van Overtake It Away: kleuren, rijders, grafieken, afbeeldingen en interactie." data-description-en="Bilingual Overtake It Away style guide: colours, drivers, charts, images and interaction." content="Tweetalige stijlgids van Overtake It Away: kleuren, rijders, grafieken, afbeeldingen en interactie."><title>Stijlgids · Overtake It Away</title><style>'+CSS+'</style></head><body data-style-guide>'
    top=tr('Naar de stijlafspraken','Skip to the design rules','a',' class="skip" href="#principles"')+'<div class="shell"><header class="guide-header"><div class="topbar"><a class="logo-link" href="index.html" aria-label="Overtake It Away · Home"><img class="guide-wordmark" src="data:image/png;base64,'+logo+'" width="2172" height="724" alt="Overtake It Away · A reality check on heroic stories."></a><nav class="tools" aria-label="Site"><a class="button" href="index.html">Home</a><a class="button red" href="races.html">Races</a>'
    top+=('<a class="button purple" href="analysis-lab.html#tab=profiles">Drivers</a>' if drivers_available else '<button class="button purple" disabled>Drivers</button>')
    top+='<button class="button" type="button" id="guide-language" aria-label="Switch to English"><span data-lang="en">EN</span> / <span data-lang="nl" class="active">NL</span></button></nav></div>'+tr('ONTWERPSYSTEEM · OVERTAKE IT AWAY','DESIGN SYSTEM · OVERTAKE IT AWAY','span',' class="eyebrow"')+tr('De meetlat voor de uitstraling.','The yardstick for the look and feel.','h1')+paragraph('Donker, scherp en gedreven door data. Vier basiskleuren geven de site een herkenbaar gezicht; de inhoud bepaalt waar een kleur betekenis heeft.','Dark, sharp and driven by data. Four core colours give the site its identity; the content determines where colour carries meaning.',' class="intro"')+'<div class="edition"><span class="chip">'+tr('Stijlgids · versie 1.0','Style guide · version 1.0')+'</span><span class="chip">15.10.2026</span><span class="chip">NL / EN</span></div></header>'
    titles=[('principles','Uitgangspunten','Principles'),('palette','Kleuren','Colours'),('type','Typografie & ruimte','Type & spacing'),('drivers','Rijders & teamkleuren','Drivers & team colours'),('components','Tegels & bediening','Cards & controls'),('charts','Grafieken & scrollen','Charts & scrolling'),('images','Afbeeldingen & beweging','Images & motion'),('interaction','Popups & navigatie','Dialogs & navigation')]
    toc='<div class="layout"><nav class="contents" aria-label="Inhoud" data-label-nl="Inhoud" data-label-en="Contents">'+tr('In deze gids','In this guide','strong')+''.join(tr(nl,en,'a',f' href="#{key}"') for key,nl,en in titles)+'</nav><main>'
    principles=paragraph('Formule 1 in sfeer. Helderheid in de analyse.','Formula 1 in atmosphere. Clarity in the analysis.',' class="lead"')+rules([
        ('Zwart en donkere panelen vormen de basis. Licht tekstcontrast en rustige grafiekvlakken houden veel gegevens leesbaar.','Black and dark panels form the foundation. Light text and calm chart surfaces keep dense information readable.'),
        ('Gebruik per tegel of module één dominant accent. De vier basiskleuren krijgen vaste rollen, geen willekeurige kleurwissels per pagina.','Use one dominant accent per card or module. The four core colours have stable roles, without arbitrary changes between pages.'),
        ('Rijdersdata volgen de teamkleur van de betreffende race en het betreffende seizoen. De huisstijl kleurt de interface, niet de identiteit van een rijder.','Driver data use the team colour from the relevant race and season. The brand palette colours the interface, not a driver’s identity.'),
        ('Kleur ondersteunt betekenis. Tekst, symbolen, markerstijl en een legenda maken dezelfde informatie ook zonder kleur begrijpelijk.','Colour supports meaning. Text, symbols, marker styles and a legend make the same information understandable without colour.'),
        ('Dit document legt de afspraken voor verdere bouw en onderhoud vast. Voorbeelden zijn illustratief en zijn geen race-uitkomsten.','This document defines the rules for further development and maintenance. Examples are illustrative, not race results.')])
    swatches='<div class="swatches">'+''.join('<article class="swatch" style="--swatch:'+value+'" data-colour="'+name+'"><div class="swatch-color"></div><div class="swatch-copy">'+tr(nl,en,'h3')+'<code>'+value+'</code>'+paragraph(role,role_en)+'</div></article>' for name,value,nl,en,role,role_en in PALETTE)+'</div>'
    accents=[('#36D398','Functioneel groen','Functional green','Betere prestatie, positiewinst en de pijl Beter. Geen extra algemene merkkleur.','Improvement, positions gained and the Better arrow. Not an additional general brand colour.'),('#F5C84C','Signaalgeel','Signal yellow','Eerstvolgende race, aftelklok en officiële gele-vlagcontext. Goud blijft de warme GOAT-kleur.','Next race, countdown and official yellow-flag context. Gold remains the warm GOAT colour.'),('#4D8DFF','Referentieblauw','Reference blue','Een extra vergelijkingsreeks wanneer het basispalet onvoldoende onderscheid geeft; nooit een vervanging van een teamkleur.','An additional comparison series when the core palette lacks distinction; never a replacement for a team colour.')]
    palette=paragraph('Deze HEX-waarden zijn het voorkeurspalet voor nieuwe en herziene onderdelen. Afgeleide transparante tinten gebruiken dezelfde kleur met een lagere dekking.','These HEX values are the preferred palette for new and revised components. Transparent variants use the same colour at lower opacity.')+swatches+'<div class="two"><article class="panel">'+tr('Functionele accentkleuren','Functional accent colours','h3')+''.join('<div class="accent-row" style="--accent:'+code+'"><i class="dot" aria-hidden="true"></i><div><strong>'+tr(nl,en)+'</strong> <code>'+code+'</code>'+paragraph(desc,desc_en)+'</div></div>' for code,nl,en,desc,desc_en in accents)+'</article><article class="panel">'+tr('Donkere ondergrond','Dark foundation','h3')+'<div class="neutral-ramp" aria-hidden="true">'+''.join('<i style="background:'+c+'"></i>' for c in ['#000000','#0E131D','#101722','#171E2A','#344053','#A7B5C8','#F3F6FB'])+'</div><table class="code-table"><tbody>'+''.join('<tr><td>'+tr(nl,en)+'</td><td><code>'+c+'</code></td></tr>' for nl,en,c in [('Banner / fotorand','Banner / photo edge','#000000'),('Pagina','Page','#0E131D'),('Grafiekvlak','Chart surface','#101722'),('Paneel','Panel','#171E2A'),('Rand / raster','Border / grid','#344053'),('Secundaire tekst','Secondary text','#A7B5C8'),('Hoofdtekst','Main text','#F3F6FB')])+'</tbody></table></article></div>'+paragraph('Gebruik accenten spaarzaam: circa 80–90% van een scherm bestaat uit donkere oppervlakken en neutrale tekst. Een status krijgt altijd een leesbaar label naast zijn kleur.','Use accents sparingly: roughly 80–90% of a screen consists of dark surfaces and neutral text. A status always has a readable label alongside its colour.',' class="note"')
    typography='<div class="two"><article class="panel">'+tr('Een snelle kop. Een rustige uitleg.','A fast headline. A calm explanation.','h3')+'<div class="sample-display">Overtake It Away</div>'+tr('2021 · Dutch Grand Prix','2021 · Dutch Grand Prix','h3')+'<div class="sample-meta"><span>Circuit Zandvoort</span>'+tr('5 september 2021','5 September 2021','small')+'</div>'+paragraph('Gebruik de lokale systeemletter: system-ui, Segoe UI of een gelijkwaardig schreefloos lettertype. De originele logoafbeelding blijft intact en staat op zuiver zwart.','Use the local system font: system-ui, Segoe UI or an equivalent sans serif. The original logo image remains intact and sits on pure black.')+'</article><article class="panel">'+tr('Vaste verhoudingen','Consistent proportions','h3')+rules([
        ('Hero: 36–64 px, gewicht 900. Grote toegangstitels mogen cursief. Moduletitels: 22–32 px, gewicht 750–850.','Hero: 36–64 px, weight 900. Large entry titles may be italic. Module titles: 22–32 px, weight 750–850.'),
        ('Lopende tekst: 15–16 px met regelafstand 1,5–1,7. Grafieklabels: circa 12 px. Kleine statuslabels blijven kort en contrastrijk.','Body text: 15–16 px with 1.5–1.7 line height. Chart labels: about 12 px. Small status labels stay brief and high contrast.'),
        ('Getallen en tijdsverschillen gebruiken cijfers met gelijke breedte. Eenheden, afronding en decimalen zijn consequent; de gekozen taal bepaalt de decimale notatie.','Numbers and time gaps use tabular numerals. Units, rounding and decimals are consistent; the selected language determines decimal notation.'),
        ('Uitlijning gaat voor versiering. Titels, beschrijvingen, statusvakken en onderknoppen van naastliggende tegels delen dezelfde rijen.','Alignment comes before decoration. Titles, descriptions, status badges and bottom actions on adjacent cards share aligned rows.')])+'</article></div><div class="tokens">'+''.join('<div class="token"><b>'+n+'</b>'+tr(nl,en)+'</div>' for n,nl,en in [('4 px','Basisritme','Base rhythm'),('12 px','Tegelradius','Card radius'),('24 px','Standaard binnenruimte','Standard padding'),('32–48 px','Ruimte tussen secties','Section spacing')])+'</div>'+paragraph('Knoppen: radius 3–5 px; grafieken: 8–9 px; popups: 12–14 px; startnummerbadges: 5 px. Gebruik 8, 12, 16, 24, 32 en 48 px voor tussenruimte. Op mobiel wordt de indeling smaller, niet de informatiedichtheid onleesbaar klein.','Buttons: 3–5 px radius; charts: 8–9 px; dialogs: 12–14 px; driver-number badges: 5 px. Use 8, 12, 16, 24, 32 and 48 px spacing. On mobile, the layout narrows without shrinking information to an unreadable size.',' class="note"')
    badges='<span class="badge" style="--team:#4781D7"><span class="number">3</span><i class="stripe"></i><span>VER</span></span><span class="flow-arrow" aria-hidden="true">→</span><span class="badge" style="--team:#ED1131"><span class="number">16</span><i class="stripe"></i><span>LEC</span></span>'
    drivers=paragraph('Altijd: nummer · teamkleur · drielettercode.','Always: number · team colour · three-letter code.',' class="lead"')+'<div class="panel"><div class="badge-demo">'+badges+'</div>'+paragraph('Vormvoorbeeld met opgeslagen teamkleuren. Het rijdernummer en de teamkleur worden in de echte interface uit de gekozen race of periode gehaald.','Format example using retained team colours. The real interface takes the driver number and team colour from the selected race or period.',' class="example-label"')+'</div>'+rules([
        ('Witte nummerbadge met afgeronde hoeken, donker cursief nummer, smalle teamkleurstreep en lichte code. Houd de afmetingen binnen één component identiek, ook bij één of drie cijfers.','White rounded number badge, dark italic number, narrow team-colour stripe and light code. Keep dimensions identical within a component, including one- or three-digit numbers.'),
        ('Rijders in uitklapmenu’s staan op achternaam, met voornaam als tweede sorteersleutel. Tussenvoegsels zoals van der en de la bepalen de volgorde niet; Jr. is geen achternaam. Naam, code en selectie veranderen niet door het sorteren.','Driver dropdowns are ordered by surname, with first name as a secondary key. Particles such as van der and de la do not determine the order; Jr. is not a surname. Sorting does not change names, codes or selection.'),
        ('Teamgenoten delen hun teamkleur. Onderscheid hen met open/gesloten markers, een subtiel verschil in helderheid en steeds een code of hoverlabel. Geen verplichte arcering over grote vlakken.','Teammates share their team colour. Distinguish them with open/filled markers, a subtle brightness difference and a code or hover label. Avoid mandatory hatching across large areas.'),
        ('Gedraaide badges hebben een vaste gereserveerde breedte en hoogte. Hun anker blijft aan de bedoelde pitstoplijn gekoppeld; tekst mag geen andere lijn, badge of as bedekken.','Rotated badges have a fixed reserved width and height. Their anchor stays attached to the relevant pit-stop line; text must not cover another line, badge or axis.'),
        ('Bij selectie blijven alle rijders en alle gegevens staan. Geselecteerde rijders krijgen volle dekking; andere rijders circa 20–30%. Referentieassen, schaal en aantallen veranderen niet door alleen te highlighten.','Selection retains every driver and every data point. Selected drivers use full opacity; others about 20–30%. Reference axes, scales and counts do not change merely from highlighting.')])
    tiles='<div class="tile-grid">'+''.join('<a class="demo-tile" href="'+{'red':'races.html','purple':'analysis-lab.html','gold':'goat.html'}[colour]+'" style="--accent:var(--brand-'+colour+')"><h3>'+label+'</h3>'+paragraph(nl,en)+'<span class="status">'+status+'</span></a>' for colour,label,nl,en,status in [('red','Races','Het archief en de raceactie.','The archive and race action.','RACE EXPLORER'),('purple','Drivers','De rijders en hun kwaliteiten.','The drivers and their qualities.','PRE-SEASON TESTING'),('gold','GOAT','Vergelijken over generaties.','Comparisons across generations.','WINTER BREAK')])+'</div>'
    if not drivers_available:
        tiles=tiles.replace('<a class="demo-tile" href="analysis-lab.html"', '<a class="demo-tile" aria-disabled="true"')
    components=tiles+'<div class="panel"><div class="component-buttons"><button class="button purple" type="button" id="guide-toggle-active" aria-pressed="true">'+tr('Actieve knop','Active button')+'</button><a href="races.html" class="button">'+tr('Naar de races','Go to races')+'</a><button class="button" disabled>'+tr('Volgend jaar','Next year')+'</button><button class="button red" type="button" id="guide-open-dialog">'+tr('Bekijk de voorbeeldpopup','Open example dialog')+'</button><button class="button gold" type="button" id="guide-print">'+tr('Stijlgids afdrukken','Print style guide')+'</button></div>'+paragraph('De paarse knop toont de actieve stijl; klik om de gekozen toestand aan of uit te zetten. Alle knoppen en interactieve tegels tonen dezelfde omlijning bij hover en klik. De uitgeschakelde knop is niet beschikbaar. De popupknop opent een werkend voorbeeld.','The purple button demonstrates the active style; click to toggle its selected state. All buttons and interactive cards use the same outline on hover and click. The disabled control is unavailable. The dialog button opens a working example.',' class="note"')+'</div>'+rules([
        ('Basisrand 1 px, gekleurde bovenrand 3 px. Een knop krijgt bij hover en activatie een accentkleurige rand, een lichtere buitenomlijning van 2 px en een subtiele gloed, zoals de knop in Pre-season testing. De gekozen toestand blijft herkenbaar zolang die actief is; een gewone actieknop gebruikt klik- of toetsenbordfocus. Interactieve kaarten krijgen dezelfde nadruk bij hover en klik. Geen sprong in maat of tekstpositie.','Use a 1 px border and 3 px coloured top rule. Hovered and activated buttons receive an accent border, a paler 2 px outer ring and a subtle glow, matching the Pre-season testing control. Selected states remain visible while active; ordinary actions use click or keyboard focus. Interactive cards receive the same emphasis on hover and click. No change in size or text position.'),
        ('Racenavigatie heeft een cyaan bovenrand. Reset, bereikverschuiving en zoom hebben dezelfde vorm, met rood als bovenrand en hoverkleur.','Race navigation has a cyan top rule. Reset, range shifting and zoom use the same shape, with a red top rule and hover.'),
        ('De frontpagina gebruikt rood voor vorige race, paars voor meest recente race en geel voor eerstvolgende race. Winnaar of aftelklok staat als echte tekst over de donkere vlagfoto.','The race catalogue uses red for the previous race, purple for the latest race and yellow for the next race. Winner or countdown appears as real text over a dark flag photo.'),
        ('Disabled is zichtbaar maar gedempt, zonder hoverbelofte en zonder klik. Een ontbrekende meting krijgt geen verzonnen 0. Een gemeten nul blijft wel zichtbaar.','Disabled controls remain visible but dimmed, without a hover promise or click. Missing measurements never become an invented zero. Measured zeros remain visible.')])
    charts=paragraph('De grafiek beweegt. De meetlat blijft staan.','The chart moves. The yardstick stays put.',' class="lead"')+paragraph('Dit voorbeeld kun je horizontaal scrollen. De y-as met Beter/Slechter blijft buiten het scrollvlak. De waarden zijn alleen een stijldemonstratie.','You can scroll this example horizontally. Its Better/Worse y-axis stays outside the scrolling region. The values are only a style demonstration.',' class="note"')+chart_example()+'<div class="legend"><span><i style="--key:#b45cff"></i>'+tr('Kwartielbereik','Interquartile range')+'</span><span><i style="--key:#fff"></i>'+tr('Mediaan','Median')+'</span><span><i style="--key:#51d6dd"></i>'+tr('Nulreferentie','Zero reference')+'</span></div>'+rules([
        ('Brede grafieken scrollen binnen hun eigen horizontale container. De pagina krijgt daardoor geen horizontale scrollbar. Y-as, waarden, eenheid en Beter/Slechter- of Sneller/Trager-pijlen blijven links staan.','Wide charts scroll inside their own horizontal container. They must not cause a horizontal page scrollbar. The y-axis, values, unit and Better/Worse or Faster/Slower arrows stay fixed on the left.'),
        ('Het muiswiel blijft de pagina verticaal scrollen. Gebruik een trackpad, Shift + muiswiel of de zichtbare horizontale scrollbar voor brede grafieken. Een focusbare container ondersteunt ook toetsenbordbediening.','The mouse wheel continues to scroll the page vertically. Use a trackpad, Shift + wheel or the visible horizontal scrollbar for wide charts. A focusable container also supports keyboard navigation.'),
        ('Op circuitkaarten zoomt uitsluitend Ctrl + muiswiel. Gewoon muiswiel mag de pagina niet vasthouden. Plus, min en volledig circuit tonen blijven als toegankelijke alternatieven beschikbaar.','Circuit maps zoom only with Ctrl + wheel. The plain wheel must not trap page scrolling. Plus, minus and fit-to-circuit controls remain accessible alternatives.'),
        ('De Starter en Tempo door de tijd gebruiken een vaste symmetrische schaal tot ±10: 0, 1, 3, 6 en 10 staan op gelijke afstand. Kleine streepjes tonen de tussenliggende gehele waarden. Noem de niet-lineaire schaal en de eenheid expliciet.','The Starter and Pace through time use a fixed symmetric scale to ±10: 0, 1, 3, 6 and 10 are equally spaced. Minor ticks show intermediate integers. Explicitly state the non-linear scale and its unit.'),
        ('Beter staat bovenaan, slechter onderaan. De Starter gebruikt gewonnen posities; de tempografiek gebruikt procentueel tijdverschil. Pas het teken correct toe zonder de ruwe gegevens te veranderen.','Better is above, worse below. The Starter uses positions gained; the pace chart uses percentage time difference. Apply the sign correctly without changing raw data.'),
        ('Uitschieters buiten de schaal blijven als randmarker bestaan, met hun werkelijke waarde in de hover. Assen, violins, punten, curve en onzekerheidsband gebruiken exact dezelfde transformatie.','Outliers beyond the scale remain as edge markers, with their actual value in the hover. Axes, violins, points, curve and uncertainty band use exactly the same transformation.'),
        ('Gebruik SVG voor lijnen, labels en markers. Een witte curve toont de fit; een grijze band met circa 20–30% dekking toont onzekerheid. Modelinschattingen bij weinig data krijgen een onderbroken lijn. Vermeld welk interval wordt getoond.','Use SVG for lines, labels and markers. A white curve shows the fit; a grey band at about 20–30% opacity shows uncertainty. Model estimates with sparse data use a dashed line. State which interval is shown.'),
        ('Hover geeft race, ronde, rijder, waarde en eenheid. Het raster blijft subtiel. Open/dicht en vormvarianten hebben een expliciete legenda; ze mogen niet ongemerkt van betekenis wisselen.','Hover provides race, lap, driver, value and unit. Grid lines stay subtle. Open/filled and shape variants have an explicit legend; their meaning must not silently change.')])+'<div class="two"><article class="panel">'+tr('Doorlopende heatmaps','Continuous heatmaps','h3')+'<div class="heatbar" aria-hidden="true"></div><div class="heat-ticks"><span>0</span><span>5</span><span>10</span><span>15</span><span>20</span><span>25</span></div>'+paragraph('Gebruik een doorlopend spectrum, geen legenda van losse blokjes. Voor aantallen: minimum 0 en maximum naar boven afgerond op een veelvoud van 5; gehele schaalwaarden in circa vier of vijf intervallen. Relatieve snelheid houdt zijn eigen vaste legenda: rood snel, blauw langzaam, grijs onbekend.','Use a continuous spectrum, not a legend of separate blocks. For counts: minimum 0 and maximum rounded up to a multiple of 5; integer scale values across roughly four or five intervals. Relative speed retains its own fixed legend: red fast, blue slow, grey unknown.')+'</article><article class="panel">'+tr('Taarten, banden en kaartpunten','Pies, tyres and map markers','h3')+paragraph('De Starter-taart gebruikt cyaan voor winst, goud voor gelijk en rood voor verlies, met percentages en tekst. Bandenkleuren blijven de betekenis van het betreffende seizoen volgen. Ze zijn geen decoratief huisstijlpalet.','The Starter pie uses cyan for gain, gold for unchanged and red for loss, with percentages and labels. Tyre colours retain their meaning for the relevant season. They are not a decorative brand palette.')+paragraph('Kaartpunten hebben 50% dekking. Bij veel acties op dezelfde plek toont het totaalbeeld alleen de heatmap; bij één tot drie acties kunnen punten worden toegevoegd. Rijrichtingspijlen liggen op de baan en krijgen geen lijn die door de pijlpunt heen steekt.','Map markers use 50% opacity. With many actions at the same location, the overview shows only the heatmap; with one to three actions, markers may be added. Direction arrows sit on the track, without a shaft protruding through the arrowhead.')+'</article></div>'
    images='<div class="flag-demo" role="img" aria-label="Abstracte demonstratie van zwart vervagende vlagranden" data-label-nl="Abstracte demonstratie van zwart vervagende vlagranden" data-label-en="Abstract demonstration of flag edges fading into black">'+tr('Hover: alleen een kleine verschuiving','Hover: only a small shift')+'</div>'+paragraph('De abstracte vlag hierboven demonstreert alleen de randen en beweging; de echte website gebruikt de gemaakte fotografische vlagafbeeldingen.','The abstract flag above demonstrates edges and motion only; the actual website uses the generated photographic flag images.',' class="note"')+rules([
        ('Fotografie is donker en filmisch: auto, helm, circuit, garage of karakteristieke locatie. Vermijd ingebakken tekst. Labels en cijfers blijven echte HTML of SVG.','Photography is dark and cinematic: car, helmet, circuit, garage or characteristic location. Avoid baked-in text. Labels and numbers remain real HTML or SVG.'),
        ('Vlaggen hebben dezelfde uitsnede en stijl. Brede zachte zwarte randen aan alle vier zijden laten ze natuurlijk opgaan in een zuiver zwarte achtergrond.','Flags share the same framing and style. Broad soft black edges on all four sides blend naturally into a pure black background.'),
        ('De drie vorige/huidige/volgende-racetegels vergroten hun vlag niet bij hover. De vlag schuift maximaal 5% naar rechts en 5% naar beneden, zonder de tekst of de tegel zelf te verplaatsen.','The three previous/latest/next race cards do not enlarge their flags on hover. The flag shifts at most 5% right and 5% down, without moving the text or the card itself.'),
        ('Andere fototegels mogen subtiel verschuiven, doorgaans circa 1–2%, maar niet plotseling inzoomen. Beweging duurt ongeveer 200–500 ms en verandert geen klikgebied.','Other photo cards may shift subtly, typically about 1–2%, without suddenly zooming in. Motion lasts about 200–500 ms and does not change the hit area.'),
        ('Een moduleachtergrond staat los van de datalaag. Zoom of pan van de circuitkaart verandert alleen de kaart, nooit de achtergrondfoto. Die foto is aan de module verankerd, geen parallax en geen schermvullende fixed-laag.','A module background is separate from the data layer. Zooming or panning a circuit map changes the map only, never the background photo. The photo is anchored to the module, without parallax or a full-screen fixed layer.'),
        ('Achtergronden achter veel informatie zijn overal rustig en donker; gebruik geen willekeurige lichtere zones. Grafiekvlakken boven fotografie mogen circa 50% dekking hebben, zolang tekst, teamkleuren en lijnen helder blijven.','Backgrounds behind dense information stay calm and dark throughout; avoid arbitrary bright zones. Chart surfaces over photography may use about 50% opacity, provided text, team colours and lines stay readable.'),
        ('Foto’s worden compact als WebP geleverd. Grafieklijnen, kaartgeometrie en tekst zijn vectoren waar mogelijk. Het bestaande pixellogo blijft de originele afbeelding op zwart. Reserveer afbeeldingsruimte vóór het laden om verspringen te voorkomen.','Deliver compact photos as WebP. Chart lines, map geometry and text use vectors where possible. The existing pixel logo remains the original image on black. Reserve image space before loading to prevent layout shifts.'),
        ('Respecteer verminderde beweging: geen hoververschuiving, draai-animatie of lange vloeiende scroll. Decoratieve beelden krijgen lege alt-tekst; informatieve beelden een beknopte beschrijving.','Respect reduced motion: no hover shift, spinning animation or long smooth scroll. Decorative images have empty alt text; informative images have a concise description.')])
    interaction=rules([
        ('Elke analysekaart, sectie en grafiek krijgt naast de titel hetzelfde paars-cyaan info-icoon. Een klik opent Pitwall briefing: een scrollbare uitlegpopup zonder timer. Kop, sluiten en terugknop blijven bereikbaar; Escape en klikken buiten de popup sluiten hem.','Every analysis card, section and chart has the same purple-cyan information icon beside its title. A click opens Pitwall briefing: a scrollable explanation dialog with no timer. Header, close and back actions remain reachable; Escape and backdrop click dismiss it.'),
        ('De popup en helppagina gebruiken één tekstbron: betekenis, eenheid, selectie, berekening, interpretatie, dekking, beperkingen en een concreet voorbeeld uit echte bewaarde gegevens. Vermeld coureurs, periode, aantallen en herkomst. Verzin geen voorbeeldpunten en verwar spreiding niet met een betrouwbaarheidsinterval.','Dialogs and the help page share one text source: meaning, unit, selection, calculation, interpretation, coverage, limitations and a concrete example from retained real observations. State drivers, period, sample sizes and provenance. Never invent example points or confuse spread with a confidence interval.'),
        ('Voorbeeldgrafieken hergebruiken de productiegrafiekfunctie: identieke asrichting, labels, schaaltransformatie, grenswaarden, afkapsymbolen, kleuren en legenda. Behoud echte race-/jaar-/circuitkoppelingen. Y-assen blijven staan; vergelijkbare voorbeelden scrollen samen. Voorbeelden zijn apart gelabeld en veranderen de paginaselectie niet. Nieuwe onderdelen zijn pas af als hun infopopup en dezelfde uitleg op de helppagina bestaan.','Example figures reuse the production chart renderer: identical axis direction, labels, scale transform, limits, clipping symbols, colours and legend. Preserve real race/year/circuit associations. Y-axes remain fixed; corresponding examples scroll together. Examples are labelled separately and never change the page selection. New modules are complete only when their information dialog and the same help-page explanation exist.'),
        ('Een klik verandert de selectie of opent details; hover toont context zonder de selectie te wijzigen. Grote start-/finishsymbolen selecteren geen rijder. De betekenis van een klik blijft voorspelbaar.','A click changes selection or opens details; hover shows context without changing selection. Large start/finish symbols do not select a driver. Click behaviour stays predictable.'),
        ('In de inhaalpopup blijft de kaart zichtbaar. Alleen het onderste kaartendeel met inhaalgegevens scrollt. Klikken op een kaartpunt scrolt dat onderste deel naar de juiste kaart en geeft die een extra kader.','In the overtake dialog, the map stays visible. Only the lower panel containing overtake cards scrolls. Clicking a map marker scrolls that lower panel to the matching card and adds an extra outline.'),
        ('Popupkop en sluitknop blijven bereikbaar. Sluiten werkt met de knop, Escape en de achtergrond. Focus blijft in de popup en keert na sluiten terug naar de opener. De pagina erachter scrollt niet mee.','The dialog heading and close button remain reachable. Close works via the button, Escape and backdrop. Focus stays inside the dialog and returns to its opener on close. The page behind it does not scroll.'),
        ('Race-/jaarwissels behouden dezelfde zichtbare module en zo veel mogelijk dezelfde uitsnede daarvan, niet blind hetzelfde aantal pixels vanaf de paginatop. De nieuwe gegevens worden voorbereid vóór de zichtbare overgang.','Race/year changes retain the same visible module and as much of its visible portion as possible, rather than blindly keeping a pixel offset from the page top. Prepare the new data before the visible transition.'),
        ('Bij laden blijft de bestaande inhoud staan waar mogelijk. Toon centraal een draaiende band als laadindicator: rood bij Races, paars bij Drivers en geel bij GOAT. Geef ook een tekststatus voor hulptechnologie. De indicator verdwijnt zodra de inhoud bruikbaar is; geen langdurig zwart tussenscherm.','Keep existing content visible while loading where possible. Show a centred spinning tyre loading indicator: red for Races, purple for Drivers and yellow for GOAT. Also provide a text status for assistive technology. Remove the indicator when the content is usable; avoid a prolonged black transition screen.'),
        ('Floating racenavigatie sluit bij scrollen aan op de lapbediening. Beide stoppen op dezelfde hoogte aan de bovenkant en bedekken geen titel of grafiek. Houd op mobiel voldoende ruimte voor tekst en aanraken.','Floating race navigation aligns with the lap controls while scrolling. Both stop at the same height at the top and do not cover titles or charts. Leave enough room for text and touch on mobile.'),
        ('De paarse terug-naar-bovenknop staat rechtsonder en bedekt geen grafiekbediening, legenda of popupknop. Bij verminderde beweging gaat de pagina direct naar boven.','The purple back-to-top button sits at the bottom right without covering chart controls, legends or dialog buttons. With reduced motion, the page returns to the top immediately.'),
        ('Nederlands en Engels zijn gelijkwaardig: dezelfde inhoud, bronverwijzingen, hoverteksten, datumnotatie en toegankelijkheidslabels in de gekozen taal. Zoek- en filtertoestanden blijven bij taalwisselen behouden.','Dutch and English are equivalent: the same content, source references, hover text, date formatting and accessibility labels in the selected language. Search and filter states survive language changes.')])+'<div class="callout">'+tr('Laat inhoud en bediening hun werk doen. De stijl maakt data begrijpelijk; hij verandert de betekenis van de data niet.','Let content and controls do their job. The style makes data understandable; it does not change what the data mean.')+'</div>'
    components=paragraph('De header bevat altijd, in deze volgorde: Home · Races · Coureurs · Greatest · About me · EN/NL. Home, Races, Coureurs en Greatest openen hun eigen bestemming; About me opent de persoonlijke popup. Coureurs heet Drivers in het Engels; de overige menunamen blijven gelijk.','The header always contains, in this order: Home · Races · Drivers · Greatest · About me · EN/NL. Home, Races, Drivers and Greatest open their own destinations; About me opens the personal dialog. The Dutch Coureurs label becomes Drivers in English; other menu labels stay the same.')+components
    bodies=[principles,palette,typography,drivers,components,charts,images,interaction]
    content=''.join(section(key,f'{i:02d}',nl,en,body) for i,((key,nl,en),body) in enumerate(zip(titles,bodies),1))
    dialog='<dialog id="guide-dialog" aria-labelledby="guide-dialog-title"><div class="dialog-head">'+tr('Voorbeeld van een popup','Example dialog','h2',' id="guide-dialog-title"')+'<button class="button" type="button" id="guide-close-dialog">'+tr('Sluiten','Close')+'</button></div><div class="dialog-content">'+paragraph('Dit is een werkend stijlvoorbeeld. De kaart blijft staan; alleen de kaarten eronder scrollen.','This is a working style example. The map stays in place; only the cards below it scroll.')+'<div class="popup-example"><div class="popup-map">'+tr('Vaste kaartzone','Fixed map area')+'</div><div class="popup-cards" tabindex="0" role="region" aria-label="Scrollbare voorbeeldkaarten" data-label-nl="Scrollbare voorbeeldkaarten" data-label-en="Scrollable example cards">'+''.join('<div class="popup-card'+(' highlight' if i==2 else '')+'">'+tr('Voorbeeldkaart '+str(i),'Example card '+str(i))+'</div>' for i in range(1,6))+'</div></div>'+paragraph('De extra cyaan rand markeert de gekoppelde kaart. De sluitknop en Escape herstellen de focus naar de opener.','The additional cyan outline marks the linked card. The close button and Escape restore focus to the opener.',' class="note"')+'</div></dialog>'
    footer='</main></div><footer class="footer"><a href="index.html">'+tr('Terug naar de startpagina','Back to the home page')+'</a><span>Overtake It Away · A reality check on heroic stories.</span></footer>'+paragraph('Zelfstandig HTML-document; opmaak, voorbeelden en taalbediening zijn ingebouwd. Interne navigatielinks werken binnen de website.','Standalone HTML document; styling, examples and language controls are built in. Internal navigation links work within the website.',' class="mode-note"')+'</div>'
    source=Path(__file__).parent
    nav_css=(source/'site-navigation.css').read_text()
    theme_css=(source/'site-theme.css').read_text()
    nav_script=(source/'site-navigation.js').read_text()
    head=head.replace('</head>','<style data-site-navigation-style>'+nav_css+'</style><style data-site-theme-style>'+theme_css+'</style></head>')
    language='<button class="button language-toggle" type="button" data-language-toggle id="guide-language" aria-label="Switch to English"><span data-lang="en">EN</span> / <span data-lang="nl" class="active">NL</span></button>'
    top=re.sub(r'<nav class="tools".*?</nav>',lambda _:'<nav class="tools header-actions" aria-label="Site">'+navigation_buttons(drivers_available=drivers_available,language_button=language)+'</nav>',top,count=1,flags=re.S)
    from .branding import with_wordmark_text
    header_css=re.sub(r"url\([^)]*\)",'none',(source/'site-header.css').read_text())
    head=head.replace('</head>','<style data-site-branding-style>'+(source/'site-branding.css').read_text()+'</style><style data-site-header-style>'+header_css+'</style></head>')
    page=head+top+toc+content+footer+dialog+'<script defer data-site-navigation-script>'+nav_script+'</script><script data-site-branding-script>'+(source/'site-branding.js').read_text()+'</script><script data-guide-script>'+SCRIPT+'</script></body></html>'
    return with_wordmark_text(page)


def build(root):
    root=Path(root);root.mkdir(parents=True,exist_ok=True)
    target=root/'stijlgids.html'
    target.write_text(render_style_guide((root/'analysis-lab.html').exists()),encoding='utf-8')
    return target
